    @staticmethod
    def _normalize_optional_size(value: float | None, name: str) -> float | None:
        if value is None:
            return None
        size = float(value)
        if not math.isfinite(size) or size < 0:
            raise ValueError(f"Pane {name} must be a non-negative finite value")
        return size

    def _effective_size(self) -> float | None:
